const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.detail||'حدث خطأ غير متوقع');return data}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className=`toast show${error?' error':''}`;clearTimeout(toast.t);toast.t=setTimeout(()=>el.className='toast',3200)}
function formatDzd(n){return new Intl.NumberFormat('fr-DZ').format(Math.round(Number(n)||0))+' دج'}
function escapeHtml(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

function switchView(name){const liveActive=$('#view-live')?.classList.contains('active');if(name!=='live'&&liveActive){if(window.LiveMarket?.__state?.mounted)window.LiveMarket.close();if(parseLiveLocation())history.pushState({},'','/')}$$('.view').forEach(v=>v.classList.remove('active'));$(`#view-${name}`)?.classList.add('active');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));window.scrollTo({top:0,behavior:'smooth'});if(name==='projects')loadProjects();if(name==='admin'){}if(name==='new')resetLabHead()}

const LIVE_DEMOS=new Set(['demo-street','demo-cafe','demo-local','demo-service','demo-food','demo-box']);
function parseLiveLocation(){const path=location.pathname.replace(/\/+$/,'');const project=path.match(/^\/projects\/([^/]+)\/live-market$/);if(project)return{projectId:decodeURIComponent(project[1]),runId:new URLSearchParams(location.search).get('run')||null};const demo=path.match(/^\/demo\/([^/]+)\/live-market$/);if(demo)return{demoId:decodeURIComponent(demo[1]),runId:null};return null}
async function openLiveMarket({projectId=null,demoId=null,runId=null,push=true}={}){if(typeof window.LiveMarket?.open!=='function')return toast('السوق الحي لم يُحمّل بعد. أعد تحديث الصفحة.',true);if(!projectId&&!demoId)return;const target=demoId?`/demo/${encodeURIComponent(demoId)}/live-market`:`/projects/${encodeURIComponent(projectId)}/live-market${runId?`?run=${encodeURIComponent(runId)}`:''}`;if(push&&location.pathname+location.search!==target){if(!parseLiveLocation())history.replaceState({...history.state,detail:demoId?{demoId}:{projectId}},'',location.pathname+location.search);history.pushState({liveMarket:true,projectId,demoId},'',target)}switchView('live');await window.LiveMarket.open({projectId,demoId,runId})}
function leaveLiveMarket(location=parseLiveLocation()){if(!location)return;if(history.state?.liveMarket){history.back();return}history.pushState({},'','/');if(location.demoId&&LIVE_DEMOS.has(location.demoId))openDemo(location.demoId);else if(location.projectId)openProject(location.projectId);else switchView('projects')}
window.addEventListener('fintwin:live-close',()=>{const location=parseLiveLocation();if(location)leaveLiveMarket(location)});
window.addEventListener('popstate',event=>{const location=parseLiveLocation();if(location){openLiveMarket({...location,push:false});return}const liveActive=$('#view-live')?.classList.contains('active');if(liveActive){if(window.LiveMarket?.__state?.mounted)window.LiveMarket.close();switchView('projects')}const detail=event.state?.detail;if(detail?.projectId)openProject(detail.projectId);else if(detail?.demoId&&LIVE_DEMOS.has(detail.demoId))openDemo(detail.demoId)});
function resetLabHead(){if(!$('.guided-form').classList.contains('hidden'))showStep(state.step)}

async function init(){
 state.meta=await api('/api/meta');
 try{state.capabilities=await api('/api/capabilities');$('#engineStatus').innerHTML=`<i></i> ${state.capabilities.llm_key_present?'محاكاة + مفتاح AI مضبوط':'محاكاة محلية · بدون AI متصل'}`}catch(e){$('#engineStatus').innerHTML='<i></i> محرك المحاكاة جاهز'}
 const sel=$('#activitySelect');sel.innerHTML=state.meta.activities.map(a=>`<option>${a.label}</option>`).join('');
 initMarketPeople();renderChips();addProductRow();addProductRow();updateUser();renderProjects();bindEvents();
 const liveRoute=parseLiveLocation();
 if(liveRoute)openLiveMarket({...liveRoute,push:false});
 else if(state.user)loadProjects();
}

