function bindEvents(){
 $$('[data-view]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();switchView(b.dataset.view);$('.topnav').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false')}));
 $('#mobileMenu').onclick=()=>{const open=$('.topnav').classList.toggle('open');$('#mobileMenu').setAttribute('aria-expanded',String(open))};
 $('#motionToggle').onclick=()=>{const paused=document.body.classList.toggle('motion-paused'),button=$('#motionToggle');button.setAttribute('aria-pressed',String(paused));button.textContent=paused?'▶ تشغيل الحركة':'Ⅱ إيقاف الحركة'};
 $$('[data-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scroll).scrollIntoView({behavior:'smooth'}));
 $('#userButton').onclick=()=>$('#loginDialog').showModal();$('.modal-close').onclick=()=>$('#loginDialog').close();
 $('#loginForm').onsubmit=login;
 $('#activitySelect').onchange=syncCustomActivity;
 $$('.intake-switch button').forEach(b=>b.onclick=()=>setIntake(b.dataset.intake));
 $('#analyzeBrief').onclick=analyzeBrief;
 $('#projectFile').onchange=e=>handleProjectFile(e.target.files[0]);
 $('#projectFileDrop').onclick=e=>{if(e.target.tagName!=='INPUT')$('#projectFile').click()};
 $('#addProduct').onclick=()=>addProductRow();
 $$('.mode-tabs button').forEach(b=>b.onclick=()=>setCatalogMode(b.dataset.catalogMode));
 $('#parsePaste').onclick=parsePastedProducts;$('#csvFile').onchange=e=>parseCsvFile(e.target.files[0]);
 $('#csvDrop').onclick=e=>{if(e.target.tagName!=='INPUT')$('#csvFile').click()};$('#downloadTemplate').onclick=downloadTemplate;
 $('#prevStep').onclick=()=>showStep(Math.max(1,state.step-1));$('#nextStep').onclick=()=>nextStep();
 $('#editBasics').onclick=()=>showStep(1);
 $('#projectForm').onsubmit=createProject;
 $('#adminUnlock').onclick=loadAdmin;
 $('#projectForm').addEventListener('input',()=>{localStorage.setItem('fintwin_draft',JSON.stringify(formSnapshot()));if(state.step===5)renderReview()});
 document.addEventListener('click',e=>{const projectButton=e.target.closest('[data-live-market]');if(projectButton){e.preventDefault();openLiveMarket({projectId:projectButton.dataset.liveMarket,runId:projectButton.dataset.liveRun||null});return}const demoButton=e.target.closest('[data-live-demo]');if(demoButton){e.preventDefault();openLiveMarket({demoId:demoButton.dataset.liveDemo})}});
}

function setIntake(mode){$$('.intake-switch button').forEach(b=>b.classList.toggle('active',b.dataset.intake===mode));$$('.smart-intake').forEach(x=>x.classList.remove('active'));$('.guided-form').classList.add('hidden');if(mode==='brief')$('#briefIntake').classList.add('active');if(mode==='file')$('#fileIntake').classList.add('active');if(mode==='guided'){$('.guided-form').classList.remove('hidden');showStep(1)}}
function syncCustomActivity(){const other=$('#activitySelect').value==='مشروع آخر';$('#customActivityField').classList.toggle('hidden',!other);$('#customActivity').required=other}

async function analyzeBrief(){const text=$('#masterBrief').value.trim();if(text.length<20)return toast('اكتب وصفاً أوضح للمشروع أولاً.',true);const btn=$('#analyzeBrief');btn.disabled=true;btn.innerHTML='نحلل العرض والفرضيات…';try{const data=await api('/api/brief/parse',{method:'POST',body:JSON.stringify({text})});fillFromBrief(data);$('.guided-form').classList.remove('hidden');$('#briefIntake').classList.remove('active');showStep(5);toast(data.extraction_mode==='llm'?'تم استخراج الفرضيات بالـAI.':'تم استخراج الأساس؛ راجع الفرضيات الناقصة.')}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.innerHTML='حلّل المشروع وعمّر الفرضيات <span>✦</span>'}}
function fillFromBrief(data){const f=$('#projectForm');if(data.project_name)f.project_name.value=data.project_name;if(data.activity_label)f.activity_label.value=data.activity_label;const c=data.config||{};['description','target_customer','stage','price','unit_cost','monthly_reach','delivery_price','delivery_cost','custom_activity'].forEach(k=>{const el=f.elements[k];if(el&&c[k]!=null)el.value=c[k]});if(c.monthly_fixed_costs!=null)f.fixed_costs.value=c.monthly_fixed_costs;if(c.wilayas)state.wilayas=new Set(c.wilayas);if(c.payment_methods)state.payments=new Set(c.payment_methods);if(c.products?.length){state.products=c.products;renderProductRows()}renderChips();syncCustomActivity()}

async function handleProjectFile(file){if(!file)return;if(file.size>2_000_000)return toast('الملف أكبر من 2MB.',true);const name=file.name.toLowerCase();if(!/\.(csv|txt|md)$/.test(name))return toast('استعمل CSV أو TXT أو MD فقط.',true);const text=await file.text();if(name.endsWith('.csv')){if(parseCsv(text)){setIntake('guided');showStep(2)}}else{$('#masterBrief').value=text;setIntake('brief');analyzeBrief()}}
function setCatalogMode(mode){$$('.mode-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.catalogMode===mode));$$('.catalog-panel').forEach(p=>p.classList.remove('active'));$(`#catalog${mode[0].toUpperCase()+mode.slice(1)}`).classList.add('active')}
function parsePastedProducts(){const lines=$('#pasteProducts').value.split(/\r?\n/).filter(Boolean);state.products=lines.map(line=>{const [name,category,price_dzd,cost_dzd,stock]=line.split('|').map(x=>x.trim());return{name,category,price_dzd,cost_dzd,stock}}).filter(p=>p.name);renderProductRows();setCatalogMode('manual');toast(`${state.products.length} عناصر تحوّلت إلى Catalog`)}
async function parseCsvFile(file){if(!file)return;if(file.size>2_000_000)return toast('ملف CSV أكبر من 2MB.',true);parseCsv(await file.text())}
function parseCsv(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(lines.length<2){toast('ملف CSV فارغ.',true);return false}const heads=splitCsv(lines.shift()).map(h=>h.trim().toLowerCase());if(!heads.includes('name')||!heads.includes('price_dzd')){toast('CSV يحتاج عمودي name و price_dzd.',true);return false}const rows=lines.map(line=>{const v=splitCsv(line),obj={};heads.forEach((h,i)=>obj[h]=v[i]?.trim()||'');return obj}).filter(x=>x.name);if(!rows.length){toast('ما لقيناش منتجات صالحة في CSV.',true);return false}if(rows.some(p=>!Number.isFinite(Number(p.price_dzd))||Number(p.price_dzd)<=0)){toast('راجع عمود السعر: كل منتج يحتاج سعراً موجباً.',true);return false}state.products=rows;renderProductRows();setCatalogMode('manual');toast(`تم استيراد ${state.products.length} منتج`);return true}
function splitCsv(line){return line.split(/,(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)/).map(v=>v.replace(/^\"|\"$/g,''))}
function downloadTemplate(){const text='name,category,price_dzd,cost_dzd,stock,monthly_sales\nقميص Oversize,ملابس,3200,1450,25,12\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download='fintwin-products-template.csv';a.click();URL.revokeObjectURL(a.href)}

function addProductRow(product={}){state.products.push({name:'',category:'',price_dzd:'',cost_dzd:'',stock:'',...product});renderProductRows()}
function renderProductRows(){const body=$('#productRows');body.innerHTML='';state.products.forEach((p,i)=>{const tr=document.createElement('tr');tr.innerHTML=`<td><input data-k="name" value="${escapeHtml(p.name)}" placeholder="اسم المنتج"></td><td><input data-k="category" value="${escapeHtml(p.category)}" placeholder="الفئة"></td><td><input data-k="price_dzd" type="number" value="${escapeHtml(p.price_dzd)}" placeholder="—"></td><td><input data-k="cost_dzd" type="number" value="${escapeHtml(p.cost_dzd)}" placeholder="—"></td><td><input data-k="stock" type="number" value="${escapeHtml(p.stock)}" placeholder="—"></td><td><button type="button" class="remove-row">×</button></td>`;tr.querySelectorAll('input').forEach(inp=>inp.oninput=()=>state.products[i][inp.dataset.k]=inp.value);tr.querySelector('.remove-row').onclick=()=>{state.products.splice(i,1);renderProductRows()};body.appendChild(tr)})}

function renderChips(){if(!state.meta)return;$('#wilayaChips').innerHTML=state.meta.wilayas.map(w=>`<button type="button" class="chip ${state.wilayas.has(w)?'active':''}" data-w="${w}">${w}</button>`).join('');$$('[data-w]').forEach(b=>b.onclick=()=>{state.wilayas.has(b.dataset.w)?state.wilayas.delete(b.dataset.w):state.wilayas.add(b.dataset.w);renderChips()});$('#paymentChips').innerHTML=state.meta.payment_methods.map(w=>`<button type="button" class="chip ${state.payments.has(w)?'active':''}" data-p="${w}">${w}</button>`).join('');$$('[data-p]').forEach(b=>b.onclick=()=>{state.payments.has(b.dataset.p)?state.payments.delete(b.dataset.p):state.payments.add(b.dataset.p);renderChips()})}

const stepCopy={1:['خلّينا نفهم المشروع','احكيلنا على الفكرة كيما تشرحها لشريك محتمل.'],2:['شنو راك تبيع؟','Catalog مرن: منتج، قائمة، أو ملف كامل.'],3:['حوّل الفكرة إلى Unit Economics','ما تعرفش رقم؟ خليه فارغ ونعلّمه كفرضية.'],4:['إشارات التجربة والثقة','أسئلة ملموسة بدل تقييمات عشوائية.'],5:['راجع وشغّل Decision Twin','المدخلات الناقصة ما تمنعكش من البداية.']};
function showStep(n){state.step=n;$$('.form-step').forEach(p=>p.classList.toggle('active',+p.dataset.stepPanel===n));$$('.steps li').forEach(p=>p.classList.toggle('active',+p.dataset.step===n));$('#stepTitle').textContent=stepCopy[n][0];$('#stepSubtitle').textContent=stepCopy[n][1];$('#progressText').textContent=`المرحلة ${n} من 5`;$('#progressBar').style.width=`${n*20}%`;$('#prevStep').classList.toggle('hidden',n===1);$('#nextStep').classList.toggle('hidden',n===5);$('#runSimulation').classList.toggle('hidden',n!==5);if(n===5)renderReview();window.scrollTo({top:70,behavior:'smooth'})}
function nextStep(){const f=$('#projectForm');if(state.step===1&&!f.project_name.value.trim())return toast('اكتب اسم المشروع أولاً.',true);if(state.step===1&&f.activity_label.value==='مشروع آخر'&&!f.custom_activity.value.trim())return toast('اكتب اسم النشاط الجديد أولاً.',true);showStep(Math.min(5,state.step+1))}
function formSnapshot(){const f=$('#projectForm');return Object.fromEntries(new FormData(f).entries())}
function signalScores(f){const trust={return_policy:{clear:12,informal:4,none:-8},social_proof:{strong:15,some:6,none:-10},price_clarity:{clear:8,partial:2,hidden:-8}},experience={visual_quality:{strong:14,basic:5,none:-8}},convenience={response_band:{fast:14,normal:6,slow:-8},access_level:{easy:12,normal:4,hard:-8}};const score=map=>Math.max(25,Math.min(90,60+Object.entries(map).reduce((sum,[field,vals])=>sum+(vals[f.elements[field]?.value]||0),0)));return{trust_score:score(trust),experience_score:score(experience),convenience_score:score(convenience)}}
function buildConfig(){const f=$('#projectForm'),num=(name)=>f.elements[name].value===''?null:Number(f.elements[name].value);return{description:f.description.value,custom_activity:f.custom_activity.value.trim(),target_customer:f.target_customer.value,stage:f.stage.value,wilayas:[...state.wilayas],products:state.products.filter(p=>p.name.trim()).map(p=>({...p,price_dzd:p.price_dzd===''?null:Number(p.price_dzd),cost_dzd:p.cost_dzd===''?null:Number(p.cost_dzd),stock:p.stock===''?null:Number(p.stock)})),offer_notes:f.offer_notes.value,price:num('price'),unit_cost:num('unit_cost'),monthly_fixed_costs:num('fixed_costs'),monthly_reach:num('monthly_reach'),delivery_price:num('delivery_price'),delivery_cost:num('delivery_cost'),payment_methods:[...state.payments],experience_notes:f.experience_notes.value,...signalScores(f)}}
function renderReview(){const f=$('#projectForm'),c=buildConfig(),filled=[f.project_name.value,c.description,c.target_customer,c.products.length,c.price,c.unit_cost,c.monthly_fixed_costs,c.monthly_reach,c.payment_methods.length].filter(Boolean).length,score=Math.round(filled/9*100);$('#readinessScore').textContent=score+'%';$('#readinessCircle').style.strokeDashoffset=100-score;$('#reviewContent').innerHTML=[['المشروع',f.project_name.value||'غير مسمى'],['النشاط',c.custom_activity||f.activity_label.value],['السوق',[...state.wilayas].join('، ')||'غير محدد'],['Catalog',c.products.length?`${c.products.length} عناصر`:'متوسط عام فقط'],['متوسط الطلب',c.price?formatDzd(c.price):'فرضية نموذجية'],['التكلفة المتغيرة',c.unit_cost?formatDzd(c.unit_cost):'فرضية نموذجية'],['قنوات الدفع',c.payment_methods.join('، ')||'غير محددة'],['وصف المشروع',c.description?c.description.slice(0,100)+'…':'غير متوفر']].map(x=>`<div class="review-card"><small>${x[0]}</small><strong>${escapeHtml(x[1])}</strong></div>`).join('')}

async function login(e){e.preventDefault();const fd=new FormData(e.currentTarget);try{const data=await api('/api/session',{method:'POST',body:JSON.stringify({name:fd.get('name'),email:fd.get('email')})});state.user={user_id:data.user_id,session_id:data.session_id,name:fd.get('name'),email:fd.get('email')};localStorage.setItem('fintwin_user',JSON.stringify(state.user));state.projects=data.projects;updateUser();renderProjects();$('#loginDialog').close();toast('مرحبا بك في Decision Lab');if(state.pendingSubmit){state.pendingSubmit=false;$('#projectForm').requestSubmit()}}catch(err){toast(err.message,true)}}
function updateUser(){$('#userButton').textContent=state.user?state.user.name:'دخول'}
async function createProject(e){e.preventDefault();if(!state.user){state.pendingSubmit=true;$('#loginDialog').showModal();return toast('دخل للتجربة، ويكمل التشغيل مباشرة.')}const f=e.currentTarget;if(!f.checkValidity()){f.reportValidity();return}const invalid=state.products.find(p=>p.name.trim()&&(!Number.isFinite(Number(p.price_dzd))||Number(p.price_dzd)<=0||p.cost_dzd!==''&&(!Number.isFinite(Number(p.cost_dzd))||Number(p.cost_dzd)<0)));if(invalid){toast(`راجع سعر وتكلفة «${invalid.name}» قبل التشغيل.`,true);showStep(2);return}const btn=$('#runSimulation');btn.disabled=true;btn.innerHTML='نبني Digital Twin…';try{const payload={user_id:state.user.user_id,name:f.project_name.value||'مشروع جديد',activity_label:f.activity_label.value,config:buildConfig()};const data=await api('/api/projects',{method:'POST',body:JSON.stringify(payload)});toast('المشروع تحوّل إلى Decision Twin');await openProject(data.project_id)}catch(err){toast(err.message,true)}finally{btn.disabled=false;btn.innerHTML='شغّل Decision Twin <span>↯</span>'}}

async function loadProjects(){if(state.user){try{state.projects=await api(`/api/users/${state.user.user_id}/projects`)}catch(e){toast(e.message,true)}}renderProjects()}
function renderProjects(){const grid=$('#projectsGrid');const real=state.projects.map(p=>`<article class="project-card" data-project="${p.id}"><div class="project-icon">◇</div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.activity_type)} · آخر تحديث ${new Date(p.updated_at).toLocaleDateString('fr-DZ')}</p><div class="project-meta"><span>Decision Twin</span><span>Scenario history</span></div><div class="mini-metrics"><div><small>STATUS</small><b>جاهز</b></div><div><small>TYPE</small><b>Live</b></div><div><small>DATA</small><b>Saved</b></div></div></article>`).join('');const demos=state.demos.map(d=>`<article class="project-card demo" data-demo="${d.id}"><div class="project-icon">${d.icon}</div><h3>${d.name}</h3><p>${d.desc}</p><div class="project-meta">${d.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="project-card-cta">حالة توضيحية <b>افتح الدراسة ↗</b></div></article>`).join('');grid.innerHTML=real+demos;$$('[data-project]',grid).forEach(c=>c.onclick=()=>openProject(c.dataset.project));$$('[data-demo]',grid).forEach(c=>c.onclick=()=>openDemo(c.dataset.demo))}
async function openProject(id,runId=null){try{const data=await api(`/api/projects/${id}`);if(runId){const selected=data.runs.find(x=>x.id===runId);if(selected)data.runs=[selected,...data.runs.filter(x=>x.id!==runId)]}renderProjectDetail(data);switchView('detail')}catch(e){toast(e.message,true)}}
async function openDemo(id){
 try{const data=await api(`/api/demo/${id}`);renderProjectDetail(data);switchView('detail')}
 catch(e){toast(e.message||'حالة العرض غير متاحة حالياً.',true)}
}
function scenarioPrompts(activity,config={},result={}){const prompts=[],weakest=(result.study_dimensions||[])[0]?.key,payments=config.payment_methods||[];if(weakest==='evidence'||weakest==='trust')prompts.push('قوي الثقة بإثباتات واضحة');if(weakest==='affordability')prompts.push('نقص السعر 8% وقارن الأثر');else if((result.purchase_intent_pct||0)>65)prompts.push('زيد السعر 7% وقارن الهامش');if(!payments.includes('بريدي موب'))prompts.push('زيد بريدي موب');if(activity==='ecommerce'){if(!config.free_delivery)prompts.push('خلي التوصيل مجاني');if((config.response_minutes||30)>15)prompts.push('اضبط الرد على 10 دقائق')}if(activity==='retail'){if(!config.fitting_rooms)prompts.push('أضف غرف القياس');if(!config.clear_prices)prompts.push('وضح الأسعار')}if(activity==='cafe'){if(!config.wifi)prompts.push('أضف Wi-Fi');if(!config.parking)prompts.push('أضف parking');prompts.push('خفض وقت الانتظار إلى 6 دقائق')}if(activity==='restaurant'){prompts.push('خفض وقت الانتظار إلى 10 دقائق');if(!config.delivery)prompts.push('فعّل التوصيل')}if(activity==='service'){if(!config.online_booking)prompts.push('فعّل الحجز أونلاين');prompts.push('اضبط الرد على 15 دقيقة')}prompts.push('زيد السعر 10% وقارن الأثر','قوي الثقة بإثباتات واضحة');return [...new Set(prompts)].slice(0,3)}
function actorStory(activity,result){const friction=result.top_objections?.[0]?.label||'التردد قبل القرار',stories={ecommerce:'نفس العرض يُقرأ بثلاث طرق: مخاطرة توصيل، صفقة جيدة، أو علامة موثوقة.',retail:'الزيارة لا تعني نية شراء واحدة؛ وضوح السعر والتجربة يغيّران القرار.',cafe:'المكان نفسه قد يكون محطة سريعة، جلسة اجتماعية، أو مساحة عمل.',restaurant:'الطعم يفتح الباب، لكن النظافة والانتظار والقيمة تحسم الرجوع.',service:'الثقة والسرعة ووضوح النتيجة تغيّر قيمة الخدمة قبل السعر.'};return {title:stories[activity]||'كل قرار تجاري يخلق ردود فعل مختلفة.',friction}}
function renderActorLab(result,config){const people=result.personas||result.persona_sample||[],story=actorStory(config.activity_key,result),prompts=scenarioPrompts(config.activity_key,config,result);return `<section class="actor-lab"><div class="actor-map-wrap"><div class="actor-map-head"><span>MARKET RELATIONSHIP GRAPH</span><span>${people.length} actors / live physics</span></div><canvas id="marketGraph" class="relationship-graph" role="img" aria-label="شبكة متحركة تبين العلاقات بين شخصيات السوق"></canvas><div id="graphTooltip" class="graph-tooltip"></div><div id="graphLegend" class="graph-legend"></div><div class="graph-hint">اسحب أي نقطة · مرّر عليها للتفاصيل</div></div><div class="actor-story"><span>DECISION INTELLIGENCE / ${escapeHtml(config.activity_key||'MARKET')}</span><h2>${escapeHtml(story.title)}</h2><div class="actor-insight"><b>THE TENSION TO EXPLORE</b><p>أقوى احتكاك ظاهر حالياً: «${escapeHtml(story.friction)}». الشبكة تجمع الناس حسب الدور، الولاية، السلوك والعرض الذي درسوه.</p></div><div class="actor-insight"><b>A DIFFERENT MOVE TO TEST</b><p>الاقتراحات أدناه مولّدة من أضعف بُعد، إعدادات النشاط والنتيجة الحالية—ماشي قائمة ثابتة.</p></div><div class="scenario-suggestions">${prompts.map(p=>`<button type="button" class="scenario-suggestion" data-scenario-prompt="${escapeHtml(p)}">${escapeHtml(p)}</button>`).join('')}</div></div></section>`}

let marketGraphRAF=0,marketGraphObserver=null;
function graphHash(text){let h=2166136261;for(const ch of String(text)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0)/4294967295}
function initMarketGraph(people,result){cancelAnimationFrame(marketGraphRAF);marketGraphObserver?.disconnect();const canvas=$('#marketGraph'),tip=$('#graphTooltip'),legend=$('#graphLegend');if(!canvas||!people.length)return;const ctx=canvas.getContext('2d'),colors=['#64fbd2','#8fd8ff','#ffc66d','#d6a8ff','#f58c80','#eef4f0'],roles=[...new Set(people.map(p=>p.market_role||p.archetype))],roleColor=new Map(roles.map((r,i)=>[r,colors[i%colors.length]]));legend.innerHTML=roles.slice(0,6).map(r=>`<span><i style="background:${roleColor.get(r)}"></i>${escapeHtml(r)}</span>`).join('');let width=0,height=0,dpr=1,frame=0,drag=null,hover=null,initialized=false;
 const nodes=[{hub:true,name:'YOUR DECISION',role:'السيناريو',x:0,y:0,vx:0,vy:0,r:16,color:'#64fbd2'}].concat(people.map((p,i)=>({p,name:p.name||`#${p.persona_id}`,role:p.market_role||p.archetype,x:0,y:0,vx:0,vy:0,r:3.4+Math.max(0,p.probability-.45)*4,color:roleColor.get(p.market_role||p.archetype),phase:graphHash(`${p.persona_id}:${p.wilaya}`)*Math.PI*2})));
 const relation=(a,b)=>{let score=0,label=[];if(a.market_role===b.market_role){score+=3;label.push('نفس الدور')}if(a.archetype===b.archetype){score+=2;label.push('سلوك متقارب')}if(a.wilaya===b.wilaya){score+=2;label.push('نفس الولاية')}if(a.preferred_channel===b.preferred_channel){score+=1;label.push('نفس القناة')}if(a.selected_offer?.name===b.selected_offer?.name){score+=1;label.push('نفس العرض')}if(a.reason_code===b.reason_code){score+=1;label.push('نفس الاحتكاك')}return{score,label:label.slice(0,2).join(' · ')}};
 const edges=[];for(let i=1;i<nodes.length;i++){const candidates=[];for(let j=1;j<i;j++){const rel=relation(nodes[i].p,nodes[j].p);if(rel.score)candidates.push({a:i,b:j,...rel,tie:graphHash(`${i}:${j}`)})}candidates.sort((a,b)=>b.score-a.score||a.tie-b.tie);for(const edge of candidates.slice(0,2))edges.push(edge);if(i%11===0||nodes[i].p.probability>.82)edges.push({a:0,b:i,score:1,label:'يتأثر مباشرة بالقرار'})}
 const resize=()=>{const rect=canvas.getBoundingClientRect();width=Math.max(320,rect.width);height=Math.max(360,rect.height);dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!initialized){nodes[0].x=width/2;nodes[0].y=height/2;nodes.slice(1).forEach((n,i)=>{const angle=(i/(nodes.length-1))*Math.PI*2+n.phase*.24,rad=70+(i%5)*33+(n.phase%1)*20;n.x=width/2+Math.cos(angle)*rad;n.y=height/2+Math.sin(angle)*rad*.72});initialized=true}};resize();marketGraphObserver=new ResizeObserver(resize);marketGraphObserver.observe(canvas);
 const physics=()=>{const cx=width/2,cy=height/2;nodes[0].x=cx;nodes[0].y=cy;for(let i=1;i<nodes.length;i++){const a=nodes[i];for(let j=i+1;j<nodes.length;j++){const b=nodes[j],dx=a.x-b.x,dy=a.y-b.y,d2=Math.max(140,dx*dx+dy*dy),force=.48/d2;a.vx+=dx*force;a.vy+=dy*force;b.vx-=dx*force;b.vy-=dy*force}}
  for(const e of edges){const a=nodes[e.a],b=nodes[e.b],dx=b.x-a.x,dy=b.y-a.y,dist=Math.max(1,Math.hypot(dx,dy)),ideal=e.a===0?145:58+e.score*6,force=(dist-ideal)*.0015;a.vx+=dx/dist*force;a.vy+=dy/dist*force;if(!b.hub){b.vx-=dx/dist*force;b.vy-=dy/dist*force}}
  for(let i=1;i<nodes.length;i++){const n=nodes[i],dx=cx-n.x,dy=cy-n.y;n.vx+=dx*.0012+Math.sin(frame*.012+n.phase)*.004;n.vy+=dy*.0012+Math.cos(frame*.009+n.phase)*.004;n.vx*=.84;n.vy*=.84;if(n!==drag){n.x+=n.vx;n.y+=n.vy}if(n.x<16||n.x>width-16)n.vx*=-.55;if(n.y<40||n.y>height-30)n.vy*=-.55;n.x=Math.max(16,Math.min(width-16,n.x));n.y=Math.max(40,Math.min(height-30,n.y))}}
 const draw=()=>{ctx.clearRect(0,0,width,height);ctx.fillStyle='#080b0a';ctx.fillRect(0,0,width,height);ctx.fillStyle='rgba(100,251,210,.10)';for(let x=18;x<width;x+=28)for(let y=24;y<height;y+=28)ctx.fillRect(x,y,1,1);for(const e of edges){const a=nodes[e.a],b=nodes[e.b];ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=e.a===0?'rgba(100,251,210,.28)':`rgba(137,176,164,${.06+e.score*.025})`;ctx.lineWidth=e.a===0?1:.55;ctx.stroke()}for(const n of nodes){ctx.beginPath();ctx.arc(n.x,n.y,n.r+(n===hover?3:0),0,Math.PI*2);ctx.fillStyle=n.hub?'#07100d':n.color;ctx.fill();ctx.strokeStyle=n.hub?'#64fbd2':'rgba(255,255,255,.75)';ctx.lineWidth=n.hub?1.5:.7;ctx.stroke();if(n.hub){ctx.fillStyle='#64fbd2';ctx.font='700 9px Manrope';ctx.textAlign='center';ctx.fillText('YOUR DECISION',n.x,n.y-1);ctx.fillStyle='#dce8e3';ctx.font='8px Alexandria';ctx.fillText((result.panel_blueprint?.activity||'SCENARIO').toUpperCase(),n.x,n.y+12)}}}
 const loop=()=>{if(!document.body.classList.contains('motion-paused'))physics();draw();frame++;canvas.dataset.frame=String(frame);canvas.dataset.sample=JSON.stringify(nodes.slice(1,5).map(n=>[+n.x.toFixed(2),+n.y.toFixed(2)]));canvas.dataset.edges=String(edges.length);window.__fintwinGraphStats={frame,nodes:nodes.length-1,edges:edges.length,moving:!document.body.classList.contains('motion-paused'),sample:nodes.slice(1,5).map(n=>[+n.x.toFixed(2),+n.y.toFixed(2)])};marketGraphRAF=requestAnimationFrame(loop)};
 const pointer=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};canvas.onpointermove=e=>{const q=pointer(e);if(drag){drag.x=q.x;drag.y=q.y;drag.vx=0;drag.vy=0}hover=nodes.reduce((best,n)=>Math.hypot(n.x-q.x,n.y-q.y)<(best?Math.hypot(best.x-q.x,best.y-q.y):14)?n:best,null);if(hover&&!hover.hub){const p=hover.p;tip.classList.add('show');tip.style.left=`${Math.min(width-190,q.x+12)}px`;tip.style.top=`${Math.max(42,q.y-18)}px`;tip.innerHTML=`<b>${escapeHtml(hover.name)}</b><span>${escapeHtml(hover.role)} · ${escapeHtml(p.wilaya)}</span><small>${Math.round(p.probability*100)}% intent · ${escapeHtml(p.reason_code||'قراءة متعددة')}</small>`}else tip.classList.remove('show')};canvas.onpointerdown=e=>{const q=pointer(e);drag=nodes.slice(1).find(n=>Math.hypot(n.x-q.x,n.y-q.y)<12)||null;if(drag)canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=()=>drag=null;canvas.onpointerleave=()=>{drag=null;hover=null;tip.classList.remove('show')};loop()}

const factorLabels={affordability:'السعر النهائي',trust:'الثقة',experience:'التجربة',convenience:'السهولة',payment:'الدفع',relevance:'ملاءمة العرض',evidence:'وضوح المعلومات'};
function renderStudyDimensions(result) {
  const blueprint = result.panel_blueprint || {};
  let dims = result.study_dimensions || [];
  if (!dims.length && result.personas?.length) {
    const sums = {}, counts = {};
    for (const p of result.personas) {
      for (const [k, v] of Object.entries(p.evaluated_factors || {})) {
        sums[k] = (sums[k] || 0) + Number(v);
        counts[k] = (counts[k] || 0) + 1;
      }
    }
    dims = Object.keys(sums).map(k => ({
      key: k,
      label: factorLabels[k] || k,
      score: Math.round(sums[k] / Math.max(1, counts[k]))
    }));
  }
  if (!dims.length) {
    const base = Math.round(result.purchase_intent_pct || 65);
    dims = [
      { key: 'affordability', label: 'السعر النهائي', score: Math.min(100, Math.round(base * 1.05)) },
      { key: 'trust', label: 'الثقة', score: Math.round(base * 0.95) },
      { key: 'experience', label: 'التجربة', score: Math.round(base * 0.92) },
      { key: 'convenience', label: 'السهولة', score: Math.min(100, Math.round(base * 1.02)) },
      { key: 'payment', label: 'الدفع', score: Math.round(base * 0.88) },
      { key: 'relevance', label: 'ملاءمة العرض', score: Math.round(base * 0.85) },
      { key: 'evidence', label: 'وضوح المعلومات', score: blueprint.evidence_score || 80 }
    ];
  }
  const evidenceScore = (blueprint.evidence_score != null && blueprint.evidence_score > 0) ? Math.round(blueprint.evidence_score) : 80;
  const targetDesc = (blueprint.target && blueprint.target !== 'حسب وصف المشروع' && blueprint.target !== 'غير محدد — تمت معاملة الملاءمة كفرضية')
    ? blueprint.target
    : 'طلبة ومستقلون وعائلات حسب طبيعة المشروع';

  return `<section class="panel method-panel">
    <div class="panel-head">
      <div>
        <span class="eyebrow">ADAPTIVE BUYER STUDY</span>
        <h3>كيفاش قُرئ هذا المشروع؟</h3>
      </div>
      <small>${blueprint.same_panel_across_scenarios ? 'نفس اللوحة بين السيناريوهات' : 'لوحة استكشافية'}</small>
    </div>
    <p class="method-copy">كل شخصية درست العرض المتاح، السعر النهائي، الثقة، التجربة، سهولة الوصول، الدفع ومدى ملاءمته لحاجتها. الفراغات تبقى فرضيات ظاهرة ولا تتحول إلى “حقائق”.</p>
    <div class="lens-grid">
      ${dims.map(d => `<div><span>${escapeHtml(d.label)}</span><b>${Math.round(d.score)}%</b><i><em style="width:${Math.max(2, Math.min(100, d.score))}%"></em></i></div>`).join('')}
    </div>
    <div class="method-meta">
      <span>الجمهور: ${escapeHtml(targetDesc)}</span>
      <span>وضوح المعطيات: ${evidenceScore}%</span>
      <span>القرارات قابلة للتتبع فرداً بفرد</span>
    </div>
  </section>`;
}
function renderPersonaStudy(p){if(!p)return '<p class="field-hint">اختار شخصية من الجدول باش تشوف الدراسة الفردية.</p>';const factors=p.evaluated_factors||{},offer=p.selected_offer||{},prices=p.price_answers||{},delta=Number(p.scenario_delta||0);return `<div class="persona-study-head"><div class="persona-avatar">${escapeHtml((p.name||'ف')[0])}</div><div><span>${escapeHtml(p.target_segment||'فاعل سوق')}</span><h4>${escapeHtml(p.name||`شخصية #${p.persona_id}`)}</h4><p>${p.age} سنة · ${escapeHtml(p.wilaya)} · دخل تقديري ${formatDzd(p.monthly_income_estimate||0)}</p></div><strong class="reaction ${p.buys?'yes':'no'}">${escapeHtml(p.reaction_label||(p.buys?'مهتم':'متردد'))}</strong></div><div class="persona-context"><div><small>الدور السوقي</small><b>${escapeHtml(p.market_role||p.archetype)}</b></div><div><small>عادة الشراء</small><b>${escapeHtml(p.buying_habit||'يقارن قبل القرار')}</b></div><div><small>الاعتراض الأول</small><b>${escapeHtml(p.initial_objection||(p.objections||[])[0]||'غير محدد')}</b></div><div><small>العرض الذي قيّمه</small><b>${escapeHtml(offer.name||'العرض الرئيسي')} · ${formatDzd(offer.price||0)}</b></div></div><div class="persona-factors">${Object.entries(factors).map(([k,v])=>`<div><span>${escapeHtml(factorLabels[k]||k)}</span><i><em style="width:${v}%"></em></i><b>${Math.round(v)}%</b></div>`).join('')}</div><blockquote>${escapeHtml(p.decision_reason||'لا توجد دراسة مفصلة في هذا التشغيل القديم.')}</blockquote><div class="persona-verdict"><p><small>وش يبدّل رأيه؟</small>${escapeHtml(p.would_change_my_mind||'إعادة تشغيل المشروع بالنسخة الجديدة')}</p>${p.previous_probability!=null?`<p><small>رد الفعل على السيناريو</small>${escapeHtml(p.scenario_reaction)} <b>${delta>=0?'+':''}${(delta*100).toFixed(1)} نقطة</b></p>`:''}<p><small>سلم السعر الشخصي</small>${prices.bargain?`${formatDzd(prices.bargain)} مناسب · ${formatDzd(prices.too_expensive)} حاجز شراء`:'يظهر بعد إعادة التشغيل'}</p></div>`}

function renderDecisionOverview(r,c={}){
 const objection=r.top_objections?.[0]?.label||'ما ظهرش اعتراض مهيمن في هاد التشغيل';
 const intent=Number(r.purchase_intent_pct||0),orders=Number(r.expected_monthly_orders||0),profit=Number(r.monthly_profit_dzd||0);
 const signal=intent>=65?'الاهتمام المقدر قوي نسبياً':intent>=45?'كاين اهتمام، لكن القرار مازال حساس':'إشارة الاهتمام ضعيفة وتحتاج اختبار العرض';
 const subscription=/نادي رياضي|لياقة|اشتراك|fitness|gym/i.test(String(c.custom_activity||''));
 const demandNoun=subscription?'اشتراكات':'طلبات';
 return `<section class="decision-overview" aria-label="قراءة النتائج"><div class="decision-overview-head"><div><span class="eyebrow">اقرأ النتيجة في دقيقة</span><h2>${signal}</h2><p>هذه محاكاة للفرضيات المدخلة، وليست مبيعات فعلية أو وعداً بالنجاح. قارن كل تغيير مع نفس نقطة البداية.</p></div><span class="evidence-badge">نتائج تقديرية · قابلة للاختبار</span></div><div class="decision-explain-grid"><article><small>01 · إشارة الاهتمام</small><strong>${intent.toFixed(1)}%</strong><p>نسبة الميل إلى الشراء داخل اللوحة الافتراضية. لا تعني نسبة تحويل الموقع.</p></article><article><small>02 · حجم الطلب</small><strong>${new Intl.NumberFormat('fr-DZ').format(orders)}</strong><p>${demandNoun} شهرية متوقعة وفق الوصول والسعر والافتراضات الحالية.</p></article><article><small>03 · الربح الشهري</small><strong>${formatDzd(profit)}</strong><p>الإيراد بعد التكاليف المقدرة. راجع المصاريف قبل اعتماد القرار.</p></article></div><div class="decision-next"><b>أول سؤال تختبره في السوق</b><span>${escapeHtml(objection)}</span><small>ابدأ بتجربة صغيرة مع زبائن حقيقيين، ثم حدّث الفرضيات بنتائجها.</small></div><p class="method-note">كيف حُسبت؟ ${Number(r.sample_size||128)} شخصية اصطناعية + مدخلات المشروع + معاملات سلوكية ومالية افتراضية. لا توجد أسعار سوق حية أو عينة ميدانية ممثلة لكل الجزائر حالياً.</p></section>`;
}
function renderScenarioComparison(comparison,changes,explanation,demo){
 const labels={purchase_intent_pct:'إشارة الاهتمام',expected_monthly_orders:'الطلبات الشهرية',monthly_revenue_dzd:'الإيراد الشهري',monthly_profit_dzd:'الربح الشهري',contribution_per_order_dzd:'هامش الطلب'};
 const isMoney=k=>k.endsWith('_dzd');
 const fmt=(k,v)=>isMoney(k)?formatDzd(v):k==='purchase_intent_pct'?`${Number(v).toFixed(1)}%`:new Intl.NumberFormat('fr-DZ').format(Math.round(Number(v)||0));
 return `<div class="scenario-comparison" role="status"><div class="scenario-comparison-head"><span class="eyebrow">نتيجة اختبار القرار</span><h4>قبل القرار وبعده</h4><p>${escapeHtml(changes?.join(' · ')||explanation||'سيناريو جديد')}</p></div><div class="comparison-list">${Object.entries(comparison||{}).filter(([k])=>labels[k]).map(([k,v])=>`<div class="comparison-item"><b>${labels[k]}</b><span>قبل<br><strong>${fmt(k,v.baseline)}</strong></span><span>بعد<br><strong>${fmt(k,v.scenario)}</strong></span><em class="${v.delta>=0?'positive':'negative'}">${v.delta>=0?'+':''}${k==='purchase_intent_pct'?`${Number(v.delta).toFixed(1)} نقطة`:fmt(k,v.delta)}</em></div>`).join('')}</div><p class="comparison-disclaimer">${demo?'حالة عرض: التغيير غير محفوظ. ':'النسخة الأصلية محفوظة للمقارنة. '}الأرقام تقديرية؛ الزيادة في مؤشر واحد لا تثبت نجاح القرار.</p></div>`;
}
function renderProjectDetail(data){const p=data.project,runs=data.runs,run=runs[0],r=run.result,c={...(p.base_config||{}),...(run.config||{})};const activityName=c.custom_activity||p.activity_type;const parent=run.parent_run_id?runs.find(x=>x.id===run.parent_run_id):null,previous=new Map((parent?.result?.personas||[]).map(x=>[x.persona_id,x]));const persons=(r.personas||r.persona_sample||[]).map(x=>{const old=previous.get(x.persona_id);if(!old)return x;const delta=x.probability-old.probability;return {...x,previous_probability:old.probability,scenario_delta:delta,scenario_reaction:delta>.035?'القرار قرّبني من الشراء':delta<-.035?'القرار زاد ترددي':'موقفي تبدل بشكل طفيف'}});$('#projectDetail').innerHTML=`
 <div class="detail-hero"><div><span class="pill lime">${data.demo?'حالة توضيحية':'توأم مشروعك'}</span><h1>${escapeHtml(p.name)}</h1><p>${escapeHtml(c.description||activityName)}</p><div class="project-meta"><span>${escapeHtml(activityName)}</span>${(c.wilayas||[]).map(w=>`<span>${w}</span>`).join('')}<span>${(c.products||[]).length} عناصر في القائمة</span></div>${data.demo?(LIVE_DEMOS.has(p.id)?`<div class="detail-actions"><button type="button" class="live-entry-btn" data-live-demo="${p.id}"><span>LIVE MARKET</span><b>شاهد رحلة الزبائن</b><small>تتبع القرارات داخل السيناريو</small></button></div>`:''):`<div class="detail-actions"><button type="button" class="live-entry-btn" data-live-market="${p.id}"><span>LIVE MARKET</span><b>شاهد رحلة الزبائن</b><small>${runs.length} تشغيل محفوظ · استكشف القرارات</small></button></div>`}</div><div class="score-block"><small>إشارة الاهتمام التقديرية</small><strong>${Number(r.purchase_intent_pct||0).toFixed(1)}<sup>%</sup></strong><small>من اللوحة الافتراضية، وليس مبيعات فعلية</small></div></div>
 ${renderDecisionOverview(r,c)}
 ${renderActorLab(r,{...c,...run.config})}
 <div class="kpi-grid"><div class="kpi-card"><span>ميل افتراضي للشراء</span><b>${r.purchase_intent_pct}%</b><small>داخل لوحة الشخصيات</small></div><div class="kpi-card"><span>تحويل تقديري</span><b>${r.expected_conversion_pct}%</b><small>من الوصول المتوقع إلى طلب</small></div><div class="kpi-card"><span>ربح شهري تقديري</span><b>${formatDzd(r.monthly_profit_dzd)}</b><small>بعد التكاليف المقدرة</small></div><div class="kpi-card"><span>نقطة التعادل</span><b>${r.break_even_orders??'—'}</b><small>طلبات لتغطية المصاريف الثابتة</small></div></div>
 ${renderStudyDimensions(r)}
 <section class="panel scenario-box scenario-wide" id="scenarioPanel"><div class="scenario-intro"><div><span class="eyebrow">SCENARIO COPILOT</span><h3>جرّب قراراً جديداً</h3><p>اكتب تغييراً واحداً أو أكثر، ثم قارن المؤشرات مع نقطة البداية. مثال: ارفع السعر 10%.</p></div><span class="evidence-badge">نفس الشخصيات · فرضية جديدة</span></div><label class="field" for="scenarioText"><span>ما الذي تريد تغييره؟</span><textarea id="scenarioText" rows="2" placeholder="مثال: ارفع السعر 10% وقارن الأثر"></textarea></label><button class="btn btn-lime" id="runScenario">قارن قبل وبعد ↗</button><div id="scenarioResponse"></div></section>
 <div class="detail-grid"><div>
  <section class="panel"><div class="panel-head"><h3>Demand signals</h3><small>نفس العرض، قراءات مختلفة</small></div><h4 class="panel-subtitle">حسب الدور في السوق</h4>${(r.market_roles||[]).map(s=>bar(s.role,s.purchase_intent)).join('')||'<p class="field-hint">يظهر التفصيل بعد تشغيل جديد.</p>'}<h4 class="panel-subtitle">حسب سلوك الشراء</h4>${(r.segments||[]).map(s=>bar(s.segment,s.purchase_intent)).join('')}</section>
  <section class="panel"><div class="panel-head"><h3>Catalog & Unit Economics</h3><small>${(c.products||[]).length} منتجات</small></div>${renderProducts(c.products||[],r,c)}</section>
  <section class="panel"><div class="panel-head"><h3>Behavioral panel</h3><small>اختار أي شخصية وشوف كيف درست المشروع</small></div><div id="personaStudy" class="persona-study">${renderPersonaStudy(persons[0])}</div><input class="persona-search" id="personaSearch" placeholder="ابحث بالاسم، الولاية، الدافع، العرض أو الاعتراض…"><div class="table-scroll" id="personaTable">${renderPersonas(persons)}</div></section>
 </div><div>
  <section class="panel"><div class="panel-head"><h3>Top friction</h3><small>اعتراضات تحتاج تجربة</small></div>${(r.top_objections||[]).map(o=>bar(o.label,Math.min(100,o.count*3),o.count)).join('')}</section>
  <section class="panel"><div class="panel-head"><h3>Payment behavior</h3><small>القناة المختارة</small></div>${Object.entries(r.payment_mix||{}).map(([k,v])=>bar(k,v,v+'%')).join('')}</section>
  <section class="panel"><div class="panel-head"><h3>What flips a “no”</h3><small>أكثر التغييرات القادرة على قلب القرار</small></div>${(r.what_flips_no||[]).map(o=>bar(o.label,Math.min(100,o.count*5),o.count)).join('')||'<p class="field-hint">افتح أي شخصية مترددة لرؤية ما يغيّر رأيها.</p>'}</section>
  <section class="panel"><div class="panel-head"><h3>${data.demo?'السيناريو الحالي ونقطة البداية':'سجل القرارات'}</h3><small>${data.demo?'المقارنة التجريبية غير محفوظة':`${runs.length} تشغيل محفوظ`}</small></div>${runs.map(x=>`<div class="run-chip"><div><b>${escapeHtml(x.scenario_name)}</b><span>${data.demo?'حالة توضيحية':new Date(x.created_at).toLocaleString('fr-DZ')}</span></div>${data.demo?(LIVE_DEMOS.has(p.id)?`<button type="button" class="live-run-btn" data-live-demo="${p.id}">السوق الحي</button>`:''):`<button type="button" class="live-run-btn" data-live-market="${p.id}" data-live-run="${x.id}">افتح السوق الحي</button>`}</div>`).join('')}</section>
 </div></div>`;
 const search=$('#personaSearch');if(search)search.oninput=()=>{const q=search.value.toLowerCase();$('#personaTable').innerHTML=renderPersonas(persons.filter(x=>JSON.stringify(x).toLowerCase().includes(q)))};
 if(!data.demo)$$('.run-chip').forEach((chip,index)=>{const view=document.createElement('button');view.type='button';view.className='live-run-btn';view.textContent='عرض النتائج';view.onclick=()=>openProject(p.id,runs[index].id);chip.appendChild(view)});
 const personaTable=$('#personaTable');if(personaTable)personaTable.onclick=e=>{const row=e.target.closest('[data-persona-id]');if(!row)return;const person=persons.find(x=>String(x.persona_id)===row.dataset.personaId);$('#personaStudy').innerHTML=renderPersonaStudy(person);$$('[data-persona-id]',personaTable).forEach(x=>x.classList.toggle('selected',x===row))};
 $$('.scenario-suggestion').forEach(button=>button.onclick=()=>{const box=$('#scenarioText');if(box){box.value=button.dataset.scenarioPrompt;$('#scenarioPanel').scrollIntoView({behavior:'smooth',block:'center'});box.focus({preventScroll:true})}});
 initMarketGraph(persons,r);
 $('#runScenario').onclick=()=>runScenario(p.id,run.parent_run_id||run.id,Boolean(data.demo))
}
function bar(label,value,display){return `<div class="bar-row"><span>${escapeHtml(label)}</span><div class="bar"><i style="width:${Math.max(2,Math.min(100,value))}%"></i></div><b>${display??value+'%'}</b></div>`}
function renderProducts(products,r,config={}){if(!products.length)return `<p class="field-hint">ماكانش Catalog مفصل؛ الحساب مبني على متوسط الطلب ${formatDzd(r.monthly_revenue_dzd/Math.max(1,r.expected_monthly_orders))}.</p>`;const reference=Number(config.catalog_reference_price||config.price),multiplier=reference>0&&Number(config.price)>0?Number(config.price)/reference:1;return `<p class="field-hint">أسعار هذا السيناريو${Math.abs(multiplier-1)>.001?' · التغيير مطبّق على كل عرض':' · كما أدخلتها'}</p><div class="table-scroll"><table class="data-table"><thead><tr><th>العرض</th><th>الفئة</th><th>السعر الحالي</th><th>التكلفة</th><th>هامش المنتج</th><th>المخزون</th></tr></thead><tbody>${products.map(p=>{const price=Number(p.price_dzd||0)*multiplier,cost=Number(p.cost_dzd||0);return `<tr><td>${escapeHtml(p.name)}</td><td>${escapeHtml(p.category||'—')}</td><td>${formatDzd(price)}</td><td>${formatDzd(cost)}</td><td>${formatDzd(price-cost)}</td><td>${p.stock??'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function renderPersonas(items){return `<table class="data-table persona-table"><thead><tr><th>الشخصية</th><th>الدور والدافع</th><th>العرض المدروس</th><th>Intent</th><th>القرار</th><th>السبب المختصر</th></tr></thead><tbody>${items.map(x=>`<tr data-persona-id="${x.persona_id}" tabindex="0"><td><b>${escapeHtml(x.name||`#${x.persona_id}`)}</b><small>${x.age} · ${escapeHtml(x.wilaya)}</small></td><td>${escapeHtml(x.market_role||'فاعل سوق')}<small>${escapeHtml(x.primary_motivation||x.archetype)}</small></td><td>${escapeHtml(x.selected_offer?.name||'العرض الرئيسي')}<small>${x.selected_offer?formatDzd(x.selected_offer.price):escapeHtml(x.preferred_channel||x.language)}</small></td><td><b>${Math.round(x.probability*100)}%</b>${x.scenario_delta?`<small class="${x.scenario_delta>0?'up':'down'}">${x.scenario_delta>0?'+':''}${(x.scenario_delta*100).toFixed(1)}</small>`:''}</td><td>${escapeHtml(x.reaction_label||(x.buys?'مهتم':'متردد'))}</td><td class="reason-cell">${escapeHtml(x.decision_reason||(x.payment||(x.objections||[]).join('، ')))}</td></tr>`).join('')}</tbody></table>`}
async function runScenario(projectId,runId,demo=false){
 const text=$('#scenarioText').value.trim();if(!text)return toast('اكتب القرار الجديد أولاً.',true);
 const btn=$('#runScenario');btn.disabled=true;btn.textContent='جاري اختبار القرار…';
 const response=$('#scenarioResponse');response.innerHTML='<div class="scenario-loading">نحسب أثر التغيير على الطلب والربح وشخصيات الزبائن…</div>';
 try{
  const endpoint=demo?`/api/demo/${projectId}/live-market/scenario`:`/api/projects/${projectId}/scenarios`;
  const d=await api(endpoint,{method:'POST',body:JSON.stringify({run_id:runId,message:text})});
  const comparison=d.comparison||{};
  if(demo){renderProjectDetail({demo:true,project:d.project_detail,runs:[d.scenario_run,d.baseline_run]})}
  else{const latest=await api(`/api/projects/${projectId}`);renderProjectDetail(latest)}
  $('#scenarioText').value=text;
  $('#scenarioResponse').innerHTML=renderScenarioComparison(comparison,d.changes,d.explanation,demo);
  $('#scenarioPanel').scrollIntoView({behavior:'smooth',block:'center'});
  toast(demo?'تمت المقارنة. هذه حالة توضيحية غير محفوظة.':'تم حفظ السيناريو وعرض المقارنة.');
 }catch(e){response.innerHTML=`<div class="scenario-error" role="alert">${escapeHtml(e.message)}</div>`;toast(e.message,true)}
 finally{const current=$('#runScenario');if(current){current.disabled=false;current.textContent='قارن قبل وبعد ↗'}}
}

async function loadAdmin(){state.adminPassword=$('#adminPassword').value;try{const d=await api('/api/admin',{method:'POST',body:JSON.stringify({password:state.adminPassword})});renderAdmin(d);$('#adminGate').classList.add('hidden');$('#adminPanel').classList.remove('hidden')}catch(e){toast(e.message,true)}}
function renderAdmin(d){const s=d.stats,labels={'Hugging Face Inference':'huggingface','DeepSeek الرسمي':'deepseek'};$('#adminPanel').innerHTML=`<div class="admin-stats">${[['المستخدمون',s.users],['المشاريع',s.projects],['Decision runs',s.runs],['LLM cost','$'+s.cost_usd.toFixed(4)]].map(x=>`<div class="kpi-card"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="admin-layout"><section class="panel"><div class="panel-head"><h3>Model routing</h3><small>Official APIs only</small></div><div class="model-row"><select id="providerPicker"><option value="huggingface" ${d.provider==='huggingface'?'selected':''}>Hugging Face Inference</option><option value="deepseek" ${d.provider==='deepseek'?'selected':''}>DeepSeek الرسمي</option></select><select id="modelPicker"></select><button id="saveModel" class="btn btn-dark">حفظ</button><button id="testModel" class="btn btn-soft">اختبر الاتصال</button></div><p id="modelTestResult" class="field-hint">وجود المفتاح لا يثبت أن الاتصال يعمل. اختبره قبل العرض.</p><div class="project-meta" style="margin-top:14px"><span>HF Token: ${d.huggingface_ready?'جاهز':'غير مضبوط'}</span><span>DeepSeek Key: ${d.deepseek_ready?'جاهز':'غير مضبوط'}</span></div></section><section class="panel"><div class="panel-head"><h3>Usage health</h3><small>آخر النشاطات</small></div>${bar('نجاح الطلبات',s.success_rate,s.success_rate+'%')}${bar('نشطون خلال 7 أيام',s.users?Math.round(s.active_users/s.users*100):0,s.active_users)}</section></div>`;const pp=$('#providerPicker'),mp=$('#modelPicker');function models(){const key=pp.value==='deepseek'?'DeepSeek الرسمي':'Hugging Face Inference';mp.innerHTML=d.providers[key].map(m=>`<option ${m===d.model?'selected':''}>${m}</option>`).join('')}pp.onchange=models;models();$('#saveModel').onclick=async()=>{try{await api('/api/admin/model',{method:'POST',body:JSON.stringify({password:state.adminPassword,provider:pp.value,model:mp.value})});toast('تم حفظ مسار الموديل')}catch(e){toast(e.message,true)}};$('#testModel').onclick=async()=>{const out=$('#modelTestResult');out.textContent='نجرب الاتصال…';try{const d=await api('/api/admin/model/test',{method:'POST',body:JSON.stringify({password:state.adminPassword,provider:pp.value,model:mp.value})});out.textContent='الاتصال ناجح · '+d.latency_ms+' ms · '+d.tokens+' tokens'}catch(e){out.textContent='فشل الاتصال: '+e.message}}}

init().catch(e=>toast(e.message,true));



